import org.jsoup.nodes.Document;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextNodeTest {

    @Test
    public void nodeNameTest() {
        TextNode node = new TextNode("sample text");
        assertEquals("#text", node.nodeName());
    }

    @Test
    public void textGetTextTest() {
        String sampleText = "sample text";
        TextNode node = new TextNode(sampleText);
        assertEquals(sampleText, node.text());
    }

    @Test
    public void textSetTextTest() {
        String newText = "new text";
        TextNode node = new TextNode("sample text");
        node.text(newText);
        assertEquals(newText, node.text());
    }

    @Test
    public void getWholeTextTest() {
        String sampleText = "sample text";
        TextNode node = new TextNode(sampleText);
        assertEquals(sampleText, node.getWholeText());
    }

    @Test
    public void isBlankTest() {
        TextNode blankNode = new TextNode("");
        assertTrue(blankNode.isBlank());

        TextNode node = new TextNode("sample text");
        assertFalse(node.isBlank());
    }

    @Test
    public void splitTextTest() {
        String sampleText = "sample text";
        TextNode node = new TextNode(sampleText);
        TextNode splitNode = node.splitText(7);
        assertEquals("sample", node.text());
        assertEquals(" text", splitNode.text());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        String sampleText = "sample text";
        TextNode node = new TextNode(sampleText);
        StringBuilder sb = new StringBuilder();
        node.outerHtmlHead(sb, 0, new Document("").outputSettings());
        assertEquals(sampleText, sb.toString());
    }

    @Test
    public void toStringTest() {
        String sampleText = "sample text";
        TextNode node = new TextNode(sampleText);
        assertEquals(sampleText, node.toString());
    }

    @Test
    public void cloneTest() {
        TextNode node = new TextNode("sample text");
        TextNode cloneNode = node.clone();
        assertNotSame(node, cloneNode);
        assertEquals(node.text(), cloneNode.text());
    }


    @Test
    public void createFromEncodedTest() {
        String encodedText = "&#xB6;"; // paragraph symbol in HTML
        TextNode node = TextNode.createFromEncoded(encodedText, null);
        assertEquals("\u00B6", node.text());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String text = "    Normalize   this  text     ";
        assertTrue("Normalize this text", TextNode.normaliseWhitespace(text).equals("Normalize this text"));
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String textWithLeadingWhitespace = "    Strip this leading whitespace";
        assertEquals("Strip this leading whitespace", TextNode.stripLeadingWhitespace(textWithLeadingWhitespace));
    }

    @Test
    public void lastCharIsWhitespaceTest() {
        StringBuilder sb = new StringBuilder("StringBuilder text ending with whitespace ");
        assertTrue(TextNode.lastCharIsWhitespace(sb));

        StringBuilder sbNoWhitespace = new StringBuilder("StringBuilder text not ending with whitespace");
        assertFalse(TextNode.lastCharIsWhitespace(sbNoWhitespace));
    }
}
